UPDATE HOSPITAL
NAME = #{name}, PHONE = #{phone, jdbcType=VARCHAR}, ZIPCODE = #{zipcode, jdbcType=VARCHAR}, ADDR1 = #{addr1, jdbcType=VARCHAR}, ADDR2 = #{addr2, jdbcType=VARCHAR}, LAT = #{lat, jdbcType=DOUBLE}, LNG = #{lng, jdbcType=DOUBLE}, DESCRIPTION = #{description, jdbcType=VARCHAR}, TAGS = #{tags, jdbcType=VARCHAR}, TIMETABLE = #{timetable, jdbcType=CLOB}
WHERE ID = #{hospitalId}
